CREATE TABLE dbo.Parent (Id int NOT NULL CONSTRAINT PK_Parent PRIMARY KEY)
GO
CREATE TABLE dbo.Child (Id int NOT NULL CONSTRAINT PK_Child PRIMARY KEY, ParentId int NULL CONSTRAINT FK_Child_Parent REFERENCES dbo.Parent (Id), OtherId int NULL)
GO
CREATE TABLE dbo.Gone (Id int NOT NULL CONSTRAINT PK_Gone PRIMARY KEY, ParentId int NULL CONSTRAINT FK_Gone_Parent REFERENCES dbo.Parent (Id))
